<script setup lang="ts">
import {onMounted,computed} from 'vue';import {ui} from '../state/device';import {command,startSimulator} from '../state/simulator';import {t} from '../state/appearance';import Icon from '../components/Icon.vue';import InfoButton from '../components/InfoButton.vue';onMounted(startSimulator);
const scenarios=computed(()=>[{id:'normal',icon:'circle-check',name:t('Обычный ритм','Normal'),description:t('Стабильная память','Stable memory')},{id:'cpu',icon:'bolt',name:t('CPU под нагрузкой','CPU load'),description:'80–90%'},{id:'leak',icon:'database',name:t('Утечка памяти','Memory leak'),description:t('RAM убывает','RAM decreases')},{id:'stack',icon:'list',name:t('Мало стека','Low stack'),description:'httpd'},{id:'weak_wifi',icon:'antenna-bars-1',name:t('Слабый Wi-Fi','Weak Wi-Fi'),description:'−86 dBm'},{id:'traffic',icon:'arrows-exchange',name:t('Активный сервер','Server traffic'),description:t('Модель CPU / RAM','CPU / RAM model')}]);
</script>
<template><aside class="panel simulator" tabindex="0" :aria-label="t('Пульт имитации','Simulator controls')"><div class="panel-head"><h2><Icon name="adjustments"/>{{t('Пульт имитации','Simulator')}}</h2><InfoButton :label="t('Пульт имитации','Simulator')" :text="t('Сценарии меняют только модель. Leak и stack не расходуют настоящую память. Traffic не генерирует сетевой трафик. Seed воспроизводит числовую модель при одинаковых командах и шагах.','Scenarios modify only the model. Leak and stack do not consume real memory. Traffic does not generate network load. A seed reproduces numerical samples with identical commands and steps.')"/></div><div class="sim-status"><span :class="ui.sim?.paused?'amber':'ok'">{{ui.sim?.paused?t('Модель на паузе','Model paused'):t('Модель выполняется','Model running')}}</span><b>×{{ui.sim?.speed??1}}</b></div><div class="sim-controls"><button :disabled="ui.pending" @click="command(ui.sim?.paused?'run':'pause')"><Icon :name="ui.sim?.paused?'player-play':'player-pause'"/>{{ui.sim?.paused?t('Продолжить','Run'):t('Пауза','Pause')}}</button><button :disabled="!ui.sim?.paused||ui.pending" @click="command('step')"><Icon name="player-track-next"/>{{t('Шаг +1 с','Step +1 s')}}</button></div><label for="model-profile">{{t('Профиль устройства','Device profile')}}</label><select id="model-profile" :value="ui.sim?.profile??'c3'" :disabled="ui.pending" @change="command('profile',($event.target as HTMLSelectElement).value)"><option value="c3">ESP32-C3 · 1 CPU</option><option value="s3">ESP32-S3 · 2 CPU · PSRAM</option></select><div class="scenario-heading">{{t('Сценарий','Scenario')}}</div><div class="scenario-list"><button v-for="s in scenarios" :key="s.id" class="scenario" :class="{active:ui.sim?.scenario===s.id}" :disabled="ui.pending" @click="command('scenario',s.id)"><Icon :name="s.icon"/><span><b>{{s.name}}</b><small>{{s.description}}</small></span><Icon v-if="ui.sim?.scenario===s.id" name="check"/></button></div><div class="scenario-heading">{{t('Скорость времени','Time scale')}}</div><div class="speed-controls"><button v-for="speed in [.25,1,2,5]" :key="speed" :class="{active:ui.sim?.speed===speed}" :disabled="ui.pending" @click="command('speed',undefined,speed)">×{{speed}}</button></div><div class="seed-row"><label for="seed">Seed</label><input id="seed" type="number" min="0" max="99999" :value="ui.sim?.seed??32" :disabled="ui.pending" @change="command('seed',undefined,Number(($event.target as HTMLInputElement).value))"></div><div class="fault-buttons"><button :disabled="ui.pending" @click="command('network')"><Icon name="antenna-bars-1"/>{{t('Потерять связь на 8 с','Disconnect for 8 s')}}</button><button :disabled="ui.pending" @click="command('disconnect')"><Icon name="plug"/>{{t('Оборвать WS','Drop WS')}}</button><button :disabled="ui.pending" @click="command('reset')"><Icon name="refresh"/>{{t('Перезапустить модель','Reset model')}}</button></div></aside></template>
<style src="./simulator.css"></style>
